Anti-Corruption Layer (ACL).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Anti_Corruption_Layer_ACL", "Anti-Corruption Layer (ACL)") {
    Component(Mainframe_Adapter, "Mainframe Adapter", "Azure App Service / Secure Mainframe Protocols", "Communicates directly with the On-Premise COBOL/DB2 Mainframe to exchange data securely.")
    Component(Message_Publisher, "Message Publisher", "Azure Service Bus SDK", "Publishes and subscribes events to the Azure Service Bus using the Outbox pattern.")
    Component(Domain_Translator, "Domain Translator", "Clean Architecture / Ports & Adapters", "Translates legacy mainframe data models into modern cloud-native domain models.")
}

Rel(Domain_Translator, Mainframe_Adapter, "Exchanges legacy data", "")
Rel(Domain_Translator, Message_Publisher, "Publishes events", "")
@enduml

Cache / Read Model Store.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Cache / Read Model Store container

Container_Boundary(cache_read_model_store, "Cache / Read Model Store") {
    Component(Read_Model_Database_Engine, "Read Model Database Engine", "Managed Cloud Database", "Stores denormalized read models to deliver fast read performance for adjuster screens and decouples read models from mainframe latency.")
    Component(In_Memory_Cache_Layer, "In-Memory Cache Layer", "Managed Cloud Cache", "Caches frequent claim queries to reduce latency for the Backend-for-Frontend (BFF).")
}

Rel(Data_Synchronization_ETL_Service, Read_Model_Database_Engine, "Database Replication")
Rel(Backend_for_Frontend_BFF, In_Memory_Cache_Layer, "TCP/Redis Protocol")

@enduml

Observability / Monitoring (Azure Applic.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(observability_monitoring_azure_application_insights, "Observability / Monitoring (Azure Application Insights)") {
    Component(Distributed_Tracing_Collector, "Distributed Tracing Collector", "Azure Application Insights / W3C Trace Context", "Collects and aggregates end-to-end distributed traces injected via HTTP headers across hybrid boundaries.")
    Component(Structured_Logging_Engine, "Structured Logging Engine", "Azure Application Insights Logging", "Captures and indexes structured log streams emitted by backend containers.")
    Component(Telemetry_Alerting_Service, "Telemetry Alerting Service", "Azure Application Insights Alerts", "Provides automated alerting and operational monitoring based on telemetry data.")
    Component(Kusto_Query_Interface, "Kusto Query Interface", "Kusto Query Language (KQL)", "Processes version-controlled query templates for rapid operational triage and monitoring.")
}

Rel(Structured_Logging_Engine, Kusto_Query_Interface, "Provides queryable log data for", "")
Rel(Distributed_Tracing_Collector, Telemetry_Alerting_Service, "Triggers alerts based on trace anomalies and failures for", "")

@enduml
